package web

import (
	"html/template"
	"time"
)

var pages = template.Must(template.New("pages").Funcs(template.FuncMap{
	"short": func(s string) string {
		if len(s) > 12 {
			return s[:12]
		}
		return s
	},
	// when renders a stored RFC 3339 timestamp as a readable UTC time inside a
	// <time> element; app.js converts it to the viewer's local time. Only
	// formatted digits are interpolated, so the HTML is safe.
	"when": func(ts string) template.HTML {
		t, err := time.Parse(time.RFC3339Nano, ts)
		if err != nil {
			return "—"
		}
		t = t.UTC()
		return template.HTML(`<time datetime="` + t.Format(time.RFC3339) + `">` + t.Format("2006-01-02 15:04 UTC") + `</time>`)
	},
	// field renders the id and, for the field named in a validation error, the
	// accessibility attributes that highlight and focus it. Names are template
	// constants, never user input.
	"field": func(errorField, name string) template.HTMLAttr {
		attrs := `id="f-` + name + `"`
		if errorField == name {
			attrs += ` aria-invalid="true" aria-describedby="form-error" autofocus`
		}
		return template.HTMLAttr(attrs)
	},
	"elapsed": func(start, end string) string {
		a, err := time.Parse(time.RFC3339Nano, start)
		if err != nil {
			return "—"
		}
		b := time.Now()
		if end != "" {
			b, _ = time.Parse(time.RFC3339Nano, end)
		}
		return b.Sub(a).Round(time.Second).String()
	},
}).Parse(`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="theme-color" content="#f2f2f7" media="(prefers-color-scheme: light)"><meta name="theme-color" content="#000000" media="(prefers-color-scheme: dark)"><title>RepoDeploy</title><link rel="icon" type="image/png" href="/static/favicon.png"><link rel="apple-touch-icon" href="/static/apple-touch-icon.png"><link rel="stylesheet" href="/static/app.css"><script src="/static/app.js" defer></script></head><body class="{{if eq .View "login"}}auth{{else}}app{{end}}"{{if .Refresh}} data-refresh="1"{{end}}>
{{if ne .View "login"}}<header class="topbar"><div class="topbar-inner"><a href="/" class="brand" aria-label="RepoDeploy home"><img src="/static/mark.png" alt="" width="149" height="96" class="brand-mark light-only"><img src="/static/mark-bright.png" alt="" width="149" height="96" class="brand-mark dark-only"><span class="wordmark">Repo<b>Deploy</b></span></a>{{if .CSRF}}<nav class="topnav" aria-label="Main"><a href="/"{{if or (eq .View "home" "project" "job" "edit" "delete" "secret" "env-value" "confirm-rollback")}} aria-current="page"{{end}}>{{template "i-grid"}}<span>Projects</span></a><a href="/connections"{{if .ConnectionView}} aria-current="page"{{end}}>{{template "i-plug"}}<span>Connections</span></a><a href="/settings"{{if or (eq .View "settings" "token")}} aria-current="page"{{end}}>{{template "i-shield"}}<span>Security</span></a><form method="post" action="/logout"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button class="ghost" title="Sign out">{{template "i-logout"}}<span>Sign out</span></button></form></nav>{{end}}</div></header>{{end}}
<main class="container">
{{if .ConnectionView}}{{template "connections" .}}{{end}}
{{if eq .View "login"}}<section class="auth-card"><div class="auth-brand"><img src="/static/mark.png" alt="" width="149" height="96" class="auth-mark light-only"><img src="/static/mark-bright.png" alt="" width="149" height="96" class="auth-mark dark-only"><p class="wordmark">Repo<b>Deploy</b></p><p class="muted">From Git to your servers.</p></div><h1>Sign in</h1>{{if .Notice}}<p class="success" role="status">{{.Notice}}</p>{{end}}{{if .Error}}<p class="notice" role="alert">{{.Error}}</p>{{end}}<form method="post" action="/login"><label for="password">Administrator password</label><input id="password" name="password" type="password" autocomplete="current-password" required autofocus><button class="block">Sign in</button></form></section>{{end}}
{{if eq .View "home"}}<div class="page-head"><div><p class="eyebrow">Dashboard</p><h1>Projects</h1><p class="lede">Deploy Git repositories or uploaded projects on this host.</p></div><div class="actions"><a class="button" href="/connections">{{template "i-plus"}}Connect a repository</a><a class="button secondary" href="/projects/new?source=upload">{{template "i-box"}}Upload a project</a></div></div>{{if .Notice}}<p class="success" role="status">{{.Notice}}</p>{{end}}
{{if .Projects}}<div class="grid projects">{{range .Projects}}{{$j := index $.Latest .ID}}<article class="card project-card"><div class="card-head"><h2><a href="/projects/{{.ID}}">{{.Name}}</a></h2>{{if $j.ID}}<a href="/jobs/{{$j.ID}}" class="status {{template "phaseClass" $j.Phase}}">{{template "phase" $j.Phase}}</a>{{else}}<span class="status idle">Never deployed</span>{{end}}</div>{{if eq .Source "upload"}}<p class="repo">Manual upload</p><ul class="chips"><li>{{template "i-box"}}upload</li>{{else}}<p class="repo" title="{{.Repo}}">{{.Repo}}</p><ul class="chips"><li>{{template "i-branch"}}{{.Branch}}</li><li>{{template "i-pulse"}}{{.Mode}}</li>{{end}}<li>{{template "i-box"}}{{if .ComposeFile}}Compose{{else}}Dockerfile{{end}}</li></ul>{{if .Blocked}}<p class="notice compact">Recovery failed · blocked</p>{{else if .Paused}}<p class="notice compact">Automation paused</p>{{end}}{{if .PollError}}<p class="notice compact">Polling failing</p>{{end}}<div class="card-foot"><small>{{if .Active}}Active release <code>{{short .Active}}</code>{{else}}No active release{{end}}</small>{{if $j.ID}}<small>{{if $j.Commit}}<code>{{short $j.Commit}}</code> · {{end}}{{if $j.Finished}}{{when $j.Finished}}{{else}}{{when $j.Created}}{{end}}</small>{{end}}</div></article>{{end}}</div>
{{else}}<section class="empty"><img src="/static/mark.png" alt="" width="149" height="96" class="empty-mark light-only"><img src="/static/mark-bright.png" alt="" width="149" height="96" class="empty-mark dark-only"><h2>No projects yet</h2><p class="muted">Connect GitHub, Bitbucket or an SSH repository, pick a branch and ship your first release.</p><p><a class="button" href="/connections">{{template "i-plug"}}Connect a repository</a></p></section>{{end}}
<details {{if not .Projects}}open{{end}}><summary>Advanced: Git URL and existing SSH files</summary>{{template "projectForm" .}}</details>{{end}}
{{define "phase"}}{{if eq . "succeeded"}}✓ Deployed{{else if eq . "failed"}}✗ Failed{{else if eq . "waiting_ci"}}Waiting for CI/CD{{else if eq . "queued"}}Queued{{else}}In progress · {{.}}{{end}}{{end}}
{{define "phaseClass"}}{{if eq . "succeeded"}}ok{{else if eq . "failed"}}failed{{else if or (eq . "queued") (eq . "waiting_ci")}}pending{{else}}running{{end}}{{end}}
{{if eq .View "project"}}<div class="page-head"><div><nav class="crumbs" aria-label="Breadcrumb"><a href="/">Projects</a><span>/</span>{{.Project.Name}}</nav><h1>{{.Project.Name}}</h1><p class="lede repo">{{if eq .Project.Source "upload"}}Manual upload{{else}}{{.Project.Repo}}{{end}}</p></div><div class="actions">{{if ne .Project.Source "upload"}}<form method="post" action="/projects/{{.Project.ID}}/deploy"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button data-confirm="Deploy the current head of {{.Project.Branch}} now?">{{template "i-rocket"}}Deploy branch</button></form>{{end}}{{if .Project.Paused}}<form method="post" action="/projects/{{.Project.ID}}/resume"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button class="secondary">Resume automation</button></form>{{end}}</div></div>
{{if .Project.Blocked}}<p class="notice">Recovery failed. Restore a retained healthy release before resuming automation. Inspect deployment logs and the host.</p>{{else if .Project.Paused}}<p class="notice">Automation is paused after rollback.</p>{{end}}{{if .Project.PollError}}<p class="notice">{{.Project.PollError}}</p>{{end}}
<dl class="stats">{{if eq .Project.Source "upload"}}<div><dt>Source</dt><dd>Manual upload</dd></div>{{else}}<div><dt>Branch</dt><dd>{{template "i-branch"}}<strong>{{.Project.Branch}}</strong></dd></div><div><dt>Detection</dt><dd>{{.Project.Mode}}</dd></div>{{end}}<div><dt>Build</dt><dd>{{if .Project.ComposeFile}}Compose · <code>{{.Project.ComposeFile}}</code>{{else}}Dockerfile · <code>{{or .Project.Dockerfile "Dockerfile"}}</code>{{end}}</dd></div><div><dt>Active release</dt><dd>{{if .Project.Active}}<code>{{short .Project.Active}}</code>{{else}}<span class="muted">None</span>{{end}}</dd></div></dl>
<section><h2>Deployment history</h2><div class="scroll"><table><thead><tr><th>{{if eq .Project.Source "upload"}}Upload{{else}}Commit{{end}}</th><th>Created</th><th>Duration</th><th>State</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>{{range .Jobs}}<tr><td><a href="/jobs/{{.ID}}" class="mono">{{if .Commit}}{{if eq $.Project.Source "upload"}}upload {{end}}{{short .Commit}}{{else}}Pending{{end}}</a>{{if eq $.Project.Active .ID}} <span class="badge">active</span>{{end}}</td><td>{{when .Created}}</td><td>{{elapsed .Started .Finished}}</td><td><span class="status {{template "phaseClass" .Phase}}">{{.Phase}}</span>{{if .Recovery}} <small class="muted">recovery {{.Recovery}}</small>{{end}}</td><td class="row-action">{{if eq .Phase "succeeded"}}<form method="post" action="/projects/{{$.Project.ID}}/rollback"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><input type="hidden" name="release_id" value="{{.ID}}"><button class="secondary small">Restore</button></form>{{end}}</td></tr>{{else}}<tr><td colspan="5" class="muted">No deployments yet.</td></tr>{{end}}</tbody></table></div></section>
<section id="env"><h2>Environment variables</h2><p class="muted">Stored on this host, never in Git. Dockerfile mode passes every variable to the container; Compose mode uses them where <code>environment:</code> or <code>build.args:</code> reference <code>${NAME}</code> or <code>${NAME:-default}</code>. Changes apply when you deploy them; restoring a release restores its values.</p>{{if .EnvPending}}<div class="notice" role="status"><p><strong>Undeployed changes.</strong> The active release runs with different values.</p><form method="post" action="/projects/{{.Project.ID}}/deploy-changes"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button>{{template "i-rocket"}}Deploy changes</button></form></div>{{end}}{{if .EnvError}}<p class="notice" role="alert">{{.EnvError}}</p>{{end}}{{if .EnvRows}}<div class="scroll"><table><thead><tr><th>Name</th><th>Value</th><th>Available</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>{{range .EnvRows}}<tr><td><code>{{.Name}}</code></td><td><span class="muted">••••••••</span></td><td>{{if .Build}}Build and runtime{{else}}Runtime{{end}}</td><td class="row-action"><form method="post" action="/projects/{{$.Project.ID}}/env/{{.Name}}/reveal"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><button class="secondary small">Show</button></form> <form method="post" action="/projects/{{$.Project.ID}}/env/{{.Name}}/delete"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><button class="secondary small" data-confirm="Delete {{.Name}}? Deploy changes afterwards to remove it from the running application.">Delete</button></form></td></tr>{{end}}</tbody></table></div>{{else}}<p class="muted">No variables yet.</p>{{end}}
<form method="post" action="/projects/{{.Project.ID}}/env" class="subform"><input type="hidden" name="_csrf" value="{{.CSRF}}"><div class="grid"><label>Name<input name="name" required maxlength="100" pattern="[A-Za-z_][A-Za-z0-9_]*" placeholder="DATABASE_URL" autocomplete="off"></label><label class="inline"><input type="checkbox" name="build"> Also available at build time (stored in the image history)</label></div><label>Value<textarea name="value" rows="2" autocomplete="off" spellcheck="false"></textarea></label><div class="form-foot"><button>Save variable</button><small>Saving an existing name replaces its value and build setting.</small></div></form>
<details><summary>Paste a .env file</summary><form method="post" action="/projects/{{.Project.ID}}/env/import" class="subform"><input type="hidden" name="_csrf" value="{{.CSRF}}"><label>.env contents<textarea name="dotenv" rows="6" autocomplete="off" spellcheck="false" placeholder="DATABASE_URL=postgres://..."></textarea></label><div class="form-foot"><button>Import variables</button><small>Existing names are replaced; their build settings are kept.</small></div></form></details></section>
<section id="secrets"><h2>Secrets and configs</h2><p class="muted">Values for Compose <code>secrets</code>/<code>configs</code> declared with <code>external: true</code>. Values are never displayed. Changes apply from the next deployment; retained releases keep the values they were deployed with.</p>{{if .SecretError}}<p class="notice" role="alert">{{.SecretError}}</p>{{end}}{{if .Secrets}}<div class="scroll"><table><thead><tr><th>Name</th><th>Value</th><th>Active release</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>{{range .Secrets}}<tr><td><code>{{.Name}}</code></td><td>{{if .Stored}}Stored · {{.Size}} bytes · {{when .Modified}}{{else}}<strong>Missing</strong>{{end}}</td><td>{{if .Required}}Required{{else}}<span class="muted">Not used</span>{{end}}</td><td class="row-action">{{if .Stored}}<form method="post" action="/projects/{{$.Project.ID}}/secrets/{{.Name}}/delete"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><button class="secondary small" data-confirm="Delete the stored value of {{.Name}}? The next deployment fails if the Compose file still needs it.">Delete</button></form>{{end}}</td></tr>{{end}}</tbody></table></div>{{else}}<p class="muted">No secrets stored.</p>{{end}}
<form method="post" action="/projects/{{.Project.ID}}/secrets" enctype="multipart/form-data" class="subform"><input type="hidden" name="_csrf" value="{{.CSRF}}"><div class="grid"><label>Name<input name="name" required maxlength="100" pattern="[A-Za-z0-9_\-]+" placeholder="app_password" autocomplete="off"></label><label>Upload a file (optional)<input name="file" type="file"></label></div><label>Or paste the value<textarea name="value" rows="4" autocomplete="off" spellcheck="false"></textarea></label><div class="form-foot"><button>Save secret</button><small>Saving an existing name replaces its value. Maximum about 1 MB.</small></div></form></section>
<details><summary>Project settings</summary>{{template "projectForm" .}}</details>{{if ne .Project.Source "upload"}}<details><summary>GitHub webhook</summary><p>Configure an HTTPS endpoint at <code>/hooks/github/{{.Project.ID}}</code>, JSON content type and push events only. Keep SSL verification enabled.</p><form method="post" action="/projects/{{.Project.ID}}/webhook-secret"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button class="secondary">Generate / rotate webhook secret</button></form><p><small class="muted">Rotating invalidates the previous secret immediately.</small></p></details>{{end}}<details class="danger"><summary>Delete project</summary><p>Stops the application, removes its containers, built images, release history, logs and stored secrets.</p><p><a class="button danger" href="/projects/{{.Project.ID}}/delete">Continue to deletion</a></p></details>{{end}}
{{if eq .View "delete"}}<div class="page-head"><div><nav class="crumbs" aria-label="Breadcrumb"><a href="/">Projects</a><span>/</span><a href="/projects/{{.Project.ID}}">{{.Project.Name}}</a></nav><h1>Delete {{.Project.Name}}?</h1></div></div><section class="danger narrow-section">{{if .Error}}<p class="notice" role="alert">{{.Error}}</p>{{end}}<p>This stops the running application and permanently removes its containers, built images, release history, logs, stored secrets and webhook secret. Provider authorizations and generated SSH keys are kept.</p><form method="post" action="/projects/{{.Project.ID}}/delete"><input type="hidden" name="_csrf" value="{{.CSRF}}"><label class="inline check"><input type="checkbox" name="volumes"> Also delete the named volumes (application data). This cannot be undone.</label><label for="confirm_name">Type <code>{{.Project.Name}}</code> to confirm</label><input id="confirm_name" name="confirm_name" autocomplete="off" required><div class="actions"><button class="danger">Delete project</button><a class="button secondary" href="/projects/{{.Project.ID}}">Cancel</a></div></form></section>{{end}}
{{if eq .View "env-value"}}<section class="narrow-section reveal"><h1><code>{{.EnvName}}</code></h1><p>Current value of this environment variable. It is only displayed in this response.</p><div class="secret-box"><span id="secret-value" class="secret-value"><code>{{.Secret}}</code></span><button type="button" class="secondary small" data-copy="secret-value">Copy</button></div><p><a href="/projects/{{.Project.ID}}#env">← Back to project</a></p></section>{{end}}
{{if eq .View "secret"}}<section class="narrow-section reveal"><h1>Webhook secret</h1><p>Copy this into GitHub's webhook settings. It is only displayed in this response.</p><div class="secret-box"><span id="secret-value" class="secret-value"><code>{{.Secret}}</code></span><button type="button" class="secondary small" data-copy="secret-value">Copy</button></div><p><a href="/projects/{{.Project.ID}}">← Back to project</a></p></section>{{end}}
{{if eq .View "job"}}<div class="page-head"><div><nav class="crumbs" aria-label="Breadcrumb"><a href="/">Projects</a><span>/</span><a href="/projects/{{.Job.ProjectID}}">{{.Job.Project.Name}}</a><span>/</span>Deployment</nav><h1>Deployment <span class="mono">{{short .Job.ID}}</span></h1></div></div><dl class="stats"><div><dt>State</dt><dd><strong id="phase" class="status {{template "phaseClass" .Job.Phase}}">{{.Job.Phase}}</strong></dd></div><div><dt>{{if eq .Job.Project.Source "upload"}}Upload{{else}}Commit{{end}}</dt><dd><code title="{{.Job.Commit}}">{{if .Job.Commit}}{{short .Job.Commit}}{{else}}—{{end}}</code></dd></div><div><dt>Recovery</dt><dd>{{or .Job.Recovery "—"}}</dd></div><div><dt>Duration</dt><dd>{{elapsed .Job.Started .Job.Finished}}</dd></div></dl>{{if .Job.Commit}}<p class="muted small-text">{{if eq .Job.Project.Source "upload"}}Upload{{else}}Commit{{end}} <code>{{.Job.Commit}}</code></p>{{end}}{{if .Job.Error}}<p class="notice">{{.Job.Error}}</p>{{end}}<div class="terminal"><div class="terminal-bar"><span></span><span></span><span></span><p>Deployment log</p></div><pre id="logs" aria-label="Deployment logs" data-log-stream="/api/jobs/{{.Job.ID}}/logs?follow=1"{{if or (eq .Job.Phase "succeeded") (eq .Job.Phase "failed")}} data-final="1"{{end}}></pre><noscript><pre>{{.Logs}}</pre></noscript></div><p><small class="muted">Logs are capped at 1 MiB per deployment. Restoring an image does not undo database migrations.</small></p>{{end}}
{{if eq .View "settings"}}<div class="page-head"><div><nav class="crumbs" aria-label="Breadcrumb"><a href="/">Projects</a><span>/</span>Security</nav><h1>Security</h1><p class="lede">Administrator password and CLI access.</p></div></div>{{if .Error}}<p class="notice" role="alert">{{.Error}}</p>{{end}}
<div class="grid two"><section><h2>Change administrator password</h2><p class="muted">Changing the password signs out every browser session, including this one. The CLI token is not affected.</p><form method="post" action="/settings/password"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="text" name="username" value="admin" autocomplete="username" hidden><label for="current_password">Current password</label><input id="current_password" name="current_password" type="password" autocomplete="current-password" required><label for="new_password">New password (at least 12 characters)</label><input id="new_password" name="new_password" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required><label for="confirm_password">Repeat new password</label><input id="confirm_password" name="confirm_password" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required><button>Change password</button></form></section>
<section><h2>CLI token</h2><p class="muted">Rotating issues a new token, stores it in <code>admin.token</code> in the state directory and immediately revokes the previous one. Remote CLI machines must receive the new token.</p><form method="post" action="/settings/token"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button class="secondary">Rotate CLI token</button></form></section></div>{{end}}
{{if eq .View "token"}}<section class="narrow-section reveal"><h1>New CLI token</h1><p>The previous token no longer works. Local commands read the new value from <code>admin.token</code> automatically. For remote machines, copy it now: it is only displayed in this response.</p><div class="secret-box"><span id="secret-value" class="secret-value"><code>{{.Secret}}</code></span><button type="button" class="secondary small" data-copy="secret-value">Copy</button></div><p><a href="/settings">← Back to security</a></p></section>{{end}}
{{define "projectForm"}}<form method="post" action="/projects{{if .Project.ID}}/{{.Project.ID}}{{end}}" class="project-form"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="connection" value="{{.Project.Connection}}"><input type="hidden" name="repository_id" value="{{.Project.RepositoryID}}">{{if .SSH.ID}}<input type="hidden" name="ssh_key_id" value="{{.SSH.ID}}">{{end}}{{if .Wizard}}<input type="hidden" name="deploy" value="1">{{end}}
{{if .FormError}}<p class="notice" role="alert" id="form-error">{{.FormError}}{{if .ErrorField}} <a href="#f-{{.ErrorField}}">Go to the field</a>{{end}}</p>{{end}}
{{if eq .Project.Source "upload"}}<input type="hidden" name="source" value="upload"><fieldset><legend>Project</legend><div class="grid"><label>Name<input {{field .ErrorField "name"}} name="name" value="{{.Project.Name}}" required maxlength="100"></label></div><p class="hint">Upload projects deploy the archive you upload from the project page or with <code>repodeploy up</code>. They have no repository, polling, webhook or CI/CD gate.</p></fieldset>{{else}}<fieldset><legend>Source and automation</legend><div class="grid">
<label>Name<input {{field .ErrorField "name"}} name="name" value="{{.Project.Name}}" required maxlength="100"></label>{{if .Wizard}}<label>Repository<code class="field-value">{{.Project.Repo}}</code><input type="hidden" name="repo" value="{{.Project.Repo}}"></label>{{else}}<label>Git URL<input {{field .ErrorField "repo"}} name="repo" value="{{.Project.Repo}}" placeholder="https://github.com/team/app.git" required></label>{{end}}
<label>Branch{{if .Branches}}<select {{field .ErrorField "branch"}} name="branch">{{range .Branches}}<option value="{{.}}" {{if eq . $.Project.Branch}}selected{{end}}>{{.}}</option>{{end}}</select>{{else}}<input {{field .ErrorField "branch"}} name="branch" value="{{.Project.Branch}}" required>{{end}}</label>
<label>Detection<select {{field .ErrorField "mode"}} name="mode"><option value="manual" {{if eq .Project.Mode "manual"}}selected{{end}}>Manual</option><option value="poll" {{if eq .Project.Mode "poll"}}selected{{end}}>Polling</option>{{if ne .Provider "bitbucket"}}<option value="webhook" {{if eq .Project.Mode "webhook"}}selected{{end}}>GitHub webhook</option><option value="both" {{if eq .Project.Mode "both"}}selected{{end}}>Webhook + polling reconciliation</option>{{end}}</select></label>
<label>Polling interval (seconds)<input {{field .ErrorField "poll_seconds"}} name="poll_seconds" type="number" value="{{if .Project.PollSeconds}}{{.Project.PollSeconds}}{{else}}60{{end}}" min="10" max="86400"></label>
<label>CI/CD<select {{field .ErrorField "wait_ci"}} name="wait_ci"><option value="" {{if not .Project.WaitCI}}selected{{end}}>Deploy immediately</option><option value="on" {{if .Project.WaitCI}}selected{{end}}>Wait for CI/CD</option></select></label><label>CI/CD timeout (seconds)<input {{field .ErrorField "ci_timeout"}} name="ci_timeout" type="number" value="{{if .Project.CITimeout}}{{.Project.CITimeout}}{{else}}1800{{end}}" min="30" max="86400"></label>
</div><p class="hint">Waiting for private CI/CD requires browser authorization for the repository provider, including when Git uses SSH.</p></fieldset>{{end}}
<fieldset><legend>Build and health</legend><div class="choice"><label class="inline"><input type="radio" {{field .ErrorField "build_type"}} name="build_type" value="dockerfile" {{if not .Project.ComposeFile}}checked{{end}}> Dockerfile</label><label class="inline"><input type="radio" name="build_type" value="compose" {{if .Project.ComposeFile}}checked{{end}}> Docker Compose</label></div>
<div class="grid build-dockerfile">
<label>Dockerfile path<input {{field .ErrorField "dockerfile"}} name="dockerfile" value="{{or .Project.Dockerfile "Dockerfile"}}"></label>
<label>Host port<input {{field .ErrorField "port"}} name="port" type="number" value="{{if .Project.Port}}{{.Project.Port}}{{else}}8080{{end}}" min="1" max="65535"></label>
<label>Container port<input {{field .ErrorField "container_port"}} name="container_port" type="number" value="{{if .Project.ContainerPort}}{{.Project.ContainerPort}}{{else}}8080{{end}}" min="1" max="65535"></label>
{{$bind := or .Project.BindAddress "127.0.0.1"}}<label>Publish port on<select {{field .ErrorField "bind_address"}} name="bind_address"><option value="127.0.0.1" {{if eq $bind "127.0.0.1"}}selected{{end}}>127.0.0.1 · this host only (recommended)</option><option value="0.0.0.0" {{if eq $bind "0.0.0.0"}}selected{{end}}>0.0.0.0 · all interfaces</option><option value="::1" {{if eq $bind "::1"}}selected{{end}}>::1 · this host only (IPv6)</option><option value="::" {{if eq $bind "::"}}selected{{end}}>:: · all interfaces (IPv6)</option>{{if not (eq $bind "127.0.0.1" "0.0.0.0" "::1" "::")}}<option value="{{$bind}}" selected>{{$bind}}</option>{{end}}</select></label>
<label>HTTP health URL<input {{field .ErrorField "health_url"}} name="health_url" value="{{if .Project.HealthURL}}{{.Project.HealthURL}}{{else}}http://127.0.0.1:8080/health{{end}}" placeholder="http://127.0.0.1:8080/health"></label>
</div>
<div class="grid build-compose">
<label>Compose path<input {{field .ErrorField "compose_file"}} name="compose_file" value="{{or .Project.ComposeFile "compose.yaml"}}"></label>
<label>Health service<input {{field .ErrorField "health_service"}} name="health_service" value="{{.Project.HealthService}}" placeholder="app"></label>
<label>HTTP health URL (optional)<input {{field .ErrorField "compose_health_url"}} name="compose_health_url" value="{{if .Project.ComposeFile}}{{.Project.HealthURL}}{{end}}" placeholder="http://127.0.0.1:18080/health"></label>
</div>
<div class="grid">
<label>Health timeout (seconds)<input {{field .ErrorField "health_timeout"}} name="health_timeout" type="number" value="{{if .Project.HealthTimeout}}{{.Project.HealthTimeout}}{{else}}60{{end}}" min="1" max="300"></label>
<label>Versions to retain<input {{field .ErrorField "retain"}} name="retain" type="number" value="{{if .Project.Retain}}{{.Project.Retain}}{{else}}5{{end}}" min="1" max="50"></label>
<label>Privilege escalation in containers<select name="privilege_escalation"><option value="" {{if not .Project.AllowPrivilegeEscalation}}selected{{end}}>Blocked with no-new-privileges (recommended)</option><option value="allow" {{if .Project.AllowPrivilegeEscalation}}selected{{end}}>Allowed (needed for setuid tools such as sudo)</option></select></label>
<label>Image updates<select name="pull_images"><option value="" {{if not .Project.PullImages}}selected{{end}}>Reuse images already on this host</option><option value="on" {{if .Project.PullImages}}selected{{end}}>Pull newer images on every deployment</option></select></label>
</div><p class="hint">Dockerfile mode needs an HTTP health URL on a loopback address. Compose mode needs a service with a Docker healthcheck, an HTTP health URL, or both.</p></fieldset>
{{if eq .Project.Source "upload"}}{{else if .Wizard}}<input type="hidden" name="ssh_key" value="{{.Project.SSHKey}}"><input type="hidden" name="known_hosts" value="{{.Project.KnownHosts}}">{{else}}<fieldset><legend>Existing SSH files (optional)</legend><div class="grid"><label>SSH private key path<input {{field .ErrorField "ssh_key"}} name="ssh_key" value="{{.Project.SSHKey}}" placeholder="/var/lib/repodeploy/keys/app"></label><label>SSH known_hosts path<input {{field .ErrorField "known_hosts"}} name="known_hosts" value="{{.Project.KnownHosts}}" placeholder="/var/lib/repodeploy/keys/known_hosts"></label></div></fieldset>{{end}}
<div class="form-foot"><button>{{if .Wizard}}{{template "i-rocket"}}Save and deploy{{else}}Save project{{end}}</button></div></form>{{end}}
{{if eq .View "edit"}}<div class="page-head"><div><nav class="crumbs" aria-label="Breadcrumb"><a href="/">Projects</a>{{if .Project.ID}}<span>/</span><a href="/projects/{{.Project.ID}}">Project</a>{{end}}</nav><h1>{{if .Project.ID}}Review project settings{{else}}Review new project{{end}}</h1></div></div><section>{{template "projectForm" .}}</section>{{end}}
{{if eq .View "confirm-rollback"}}<div class="page-head"><div><nav class="crumbs" aria-label="Breadcrumb"><a href="/">Projects</a><span>/</span><a href="/projects/{{.Project.ID}}">{{.Project.Name}}</a></nav><h1>Restore release <span class="mono">{{short .Job.ID}}</span>?</h1></div></div><section class="narrow-section"><p>Commit <code>{{.Job.Commit}}</code>, deployed {{when .Job.Finished}}.</p><ul class="checklist"><li>Automatic deployments for this project are <strong>paused</strong> until you resume them.</li><li>Database migrations and data written since that release are <strong>not</strong> undone.</li><li>The secrets and configs captured with that release are restored, even if you rotated them since.</li></ul><div class="actions"><form method="post" action="/projects/{{.Project.ID}}/rollback"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="release_id" value="{{.Job.ID}}"><input type="hidden" name="confirm" value="1"><button>Restore this release</button></form><a class="button secondary" href="/projects/{{.Project.ID}}">Cancel</a></div></section>{{end}}
</main>
<footer class="footer"><span class="wordmark">Repo<b>Deploy</b></span><span>From Git to your servers.</span></footer>
{{define "i-grid"}}<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></svg>{{end}}
{{define "i-plug"}}<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M9 2v5M15 2v5M6 7h12v4a6 6 0 0 1-12 0V7zM12 17v5"/></svg>{{end}}
{{define "i-shield"}}<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3l8 3v6c0 4.5-3.4 8.3-8 9-4.6-.7-8-4.5-8-9V6l8-3z"/><path d="M9 12l2 2 4-4"/></svg>{{end}}
{{define "i-logout"}}<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M15 4h3a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-3M10 17l-5-5 5-5M5 12h11"/></svg>{{end}}
{{define "i-plus"}}<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>{{end}}
{{define "i-branch"}}<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="6" cy="5" r="2"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="7" r="2"/><path d="M6 7v10M18 9c0 5-6 4-11.5 8.5"/></svg>{{end}}
{{define "i-pulse"}}<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 12h4l3-7 4 14 3-7h4"/></svg>{{end}}
{{define "i-box"}}<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M21 8l-9-5-9 5 9 5 9-5zM3 8v8l9 5 9-5V8M12 13v8"/></svg>{{end}}
{{define "i-rocket"}}<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19l3-3M14 4c3.5 0 6 2.5 6 6l-7 7-6-6 7-7zM7 11l-3 1-1 3 4-1M13 17l-1 3-3 1 1-4"/><circle cx="15" cy="9" r="1.5"/></svg>{{end}}
{{define "i-key"}}<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="8" cy="15" r="4"/><path d="M11 12l9-9M17 6l3 3M14 9l2 2"/></svg>{{end}}
</body></html>`))
